import java.util.Locale;

public final class Tag implements Comparable<Tag> {
    private final String text;
    private final String key;

    private Tag(String text) {
        this.text = text;
        this.key = text.toLowerCase(Locale.ROOT);
    }

    public static Tag of(String text) {
        String trimmed = text.trim();
        if (trimmed.isEmpty()) throw new IllegalArgumentException("a tag cannot be blank");
        return new Tag(trimmed);
    }

    @Override
    public boolean equals(Object o) {
        return this == o || (o instanceof Tag other && key.equals(other.key));
    }

    @Override
    public int hashCode() {
        return key.hashCode();
    }

    @Override
    public int compareTo(Tag other) {
        return key.compareTo(other.key);
    }

    @Override
    public String toString() {
        return text;
    }
}

solution.Tags.java:
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

public class Tags {
    public static Set<Tag> distinct(List<String> raw) {
        Set<Tag> tags = new TreeSet<>();
        for (String s : raw) tags.add(Tag.of(s));      // add keeps the first one when an equal tag is there
        return tags;
    }
}

unitTests:
test("equality ignores case", () -> {
    check(Tag.of("Java").equals(Tag.of(" JAVA ")), "case and spaces should not matter");
    checkEq(Tag.of("Java").hashCode(), Tag.of("java").hashCode());
    checkEq(Tag.of(" Rust ").toString(), "Rust");
    checkThrows(IllegalArgumentException.class, () -> Tag.of("   "));
});

test("consistent order", () -> {
    checkEq(Tag.of("go").compareTo(Tag.of("GO")), 0);
    check(Tag.of("Go").compareTo(Tag.of("java")) < 0, "Go comes before java");
    check(Tag.of("rust").compareTo(Tag.of("Java")) > 0, "rust comes after Java");
});

test("distinct tags", () -> {
    checkEq(Tags.distinct(java.util.List.of("Java", "rust", " JAVA ", "Go", "java")).toString(), "[Go, Java, rust]");
    var hash = new java.util.HashSet<Tag>(java.util.List.of(Tag.of("a"), Tag.of("A")));
    checkEq(hash.size(), 1);
});

